using Godot;
using Godot.Collections;

// One paragraph of a ConversationBranch: its localized text plus the actions
// that bracket it. Generated by tools/conversation_import from a sheet row's
// `on start` / `on complete` cells.
[GlobalClass]
public partial class ConversationLine : Resource
{
    // Resolved via Loc.Get at speak time.
    [Export] public StringName locKey;

    // Fired as the paragraph starts typing (a `vocalize` grunt belongs here).
    [Export] public Array<ConversationAction> startActions;

    // Fired when the player advances past the paragraph. On a branch's last
    // paragraph that is before the exit group's chooser is built, so an action
    // that closes the panel (OpenShopAction) suppresses the chooser.
    [Export] public Array<ConversationAction> completeActions;
}
